// Validate Features: rings that are not closed.
export function openRings(features) {
  const problems = [];
  for (const feature of features) {
    for (const [index, ring] of (feature.geometry?.rings ?? []).entries()) {
      const [x0, y0] = ring[0];
      const [xn, yn] = ring[ring.length - 1];
      if (x0 !== xn || y0 !== yn) problems.push({ id: feature.id, ring: index });
    }
  }
  return problems;
}

