function ringOf(text) {
  const t = (text ?? '').trim();
  return t ? t.split(/\s+/).map((pair) => pair.split(',').map(Number)) : [];
}

// KML Polygon to rings: the outer boundary, then each inner boundary.
export function polygonRings(polygon) {
  const rings = [ringOf(polygon.outer)];
  for (const text of polygon.inner) rings.push(ringOf(text));
  return rings;
}

